/* isry.aimns.casemng.mapper.AimnsCaseMngMapper.selectEduComplSchdl */
/* 교육이수일정 조회 - Lee SangHoon */

SELECT

   CASE_MNG_NO
   ,CASE_MNG_ODRNO
   ,BGNG_YMD
   ,END_YMD
   ,FNSH_YMD

FROM AFA330
WHERE CASE_MNG_NO = #{CASE_MNG_NO}
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

mapper.insert:

/* isry.aimns.casemng.mapper.AimnsCaseMngMapper.insertEduComplSchdl */
/* 교육이수일정 등록 - Lee SangHoon */

INSERT INTO AFA330(

    CASE_MNG_NO
    ,CASE_MNG_ODRNO

    ,BGNG_YMD
    ,END_YMD
    ,FNSH_YMD

    ,FRST_RGTR_ID
    ,LAST_MDFR_ID

)VALUES(

    #{CASE_MNG_NO}
    ,#{CASE_MNG_ODRNO}

    ,#{BGNG_YMD}
    ,#{END_YMD}
    ,#{FNSH_YMD}

    ,#{FRST_RGTR_ID}
    ,#{LAST_MDFR_ID}

)

mapper.update:

/* isry.aimns.casemng.mapper.AimnsCaseMngMapper.updateEduComplSchdl */
/* 교육이수일정 수정 - Lee SangHoon */

UPDATE AFA330 SET

    BGNG_YMD = #{BGNG_YMD}
    ,END_YMD = #{END_YMD}
    ,FNSH_YMD = #{FNSH_YMD}

    ,LAST_MDFR_ID = #{LAST_MDFR_ID}
    ,LAST_MDFCN_DT = SYSDATE

WHERE 1=1
AND CASE_MNG_NO = #{CASE_MNG_NO__origin}
AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO__origin}

mapper.select:
SELECT
/* isry.aimns.casemng.mapper.AimnsCaseMngMapper */ #{TOT_CNT} TOT_CNT , T1.* FROM ( SELECT /*+ INDEX_DESC(T1 SEB100_IDX1)*/ T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , TO_CHAR(T1.FRST_REG_DT, 'YYYY-MM-DD') AS FRST_REG_DT /* 등록일자 */ , T2.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , DEC_B64(T2.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /* 대상자명 */ , CASE WHEN REPLACE(T2.TRPR_BRTH_YMD, '-', '') = '00000000' THEN '' ELSE TO_CHAR(TO_DATE(REPLACE(T2.TRPR_BRTH_YMD, '-', '')), 'YYYY-MM-DD') END AS TRPR_BRTH_YMD /* 대상자출생일자 */ , T2.SXDC_SE_CD AS SXDC_SE_CD /* 대상자성별구분코드 */ , T1.YNGBGS_STTS_LCLAS_SE_CD AS YNGBGS_STTS_LCLAS_SE_CD /* 청소년상태대분류구분코드 */ , T1.YNGBGS_STTS_SCLAS_SE_CD AS YNGBGS_STTS_SCLAS_SE_CD /* 청소년상태소분류구분코드 */ , T1.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , DEC_B64(X.FLNM_ENCPT) AS PIC_NM_ENCPT /* 담당자명(주담당자기준) */ , Y.PIC_INST_NO AS PIC_INST_NO /* 담당기관(주담당자기준) */ , CASE WHEN X.JBPS_NM IS NOT NULL THEN X.JBPS_NM ELSE (SELECT TT1.CMMNS_CD_VALUE_NM FROM SAC100 TT1 WHERE TT1.CMMNS_CD_ID = 'JBPS_SE_CD' AND TT1.CMMNS_CD_VALUE = X.JBPS_SE_CD) END AS JBPS_NM /* 담당자직위명(주담당자기준) */ , X.JBPS_SE_CD AS JBPS_SE_CD /* 담당자직위구분코드(주담당자기준) */ , Z.INST_NM AS INST_NM /* 담당기관명(주담당자기준) */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , (SELECT UP_CMMNS_CD_VALUE FROM SAC100 WHERE CMMNS_CD_ID = 'CASE_PRGRS_STTS_SE_CD' AND CMMNS_CD_VALUE = T1.CASE_PRGRS_STTS_SE_CD) AS CASE_PRGRS_STTS_TYPE_SE_CD /* 사례진행상태유형구분코드 */
/* 2022.08.22 * - 권한적용을 위한 항목 추가 */ , ( SELECT LISTAGG(X.CASE_PIC_NO, ',') WITHIN GROUP (ORDER BY X.PCHPRS_YN DESC, X.CASE_PIC_NO) FROM SEB150 X WHERE X.CASE_MNG_NO = T1.CASE_MNG_NO AND X.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO ) AS ENFSN_NO , ( SELECT LISTAGG(X.PIC_INST_NO, ',') WITHIN GROUP (ORDER BY X.PCHPRS_YN DESC, X.CASE_PIC_NO) FROM SEB150 X WHERE X.CASE_MNG_NO = T1.CASE_MNG_NO AND X.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO ) AS INST_NO
, T2.TRMN_CASE_MNG_NO AS TRMN_CASE_MNG_NO /* 종결사례관리번호 */ , T2.TRMN_CASE_MNG_ODRNO AS TRMN_CASE_MNG_ODRNO /* 종결사례관리차수 */ , TO_CHAR(T2.MDFCN_DT, 'YYYYMMDDHH24MISS') AS SEA201_MDFCN_DT /* 수정일시(SEA201) */ , T1.CASE_BGNG_YMD AS CASE_BGNG_YMD , T1.CASE_TRMN_YMD AS CASE_TRMN_YMD , CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '01' THEN 'REG' /* 등록 */ WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('02','03','06','12') THEN 'PRGRS' /* 진행 */ WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('04','08','10') THEN 'TRMN' /* 종결 */ ELSE '' END AS STEP_SE , T2.RCPT_PIC_NO AS RCPT_PIC_NO , Z.CTPV_CD AS CTPV_CD , T1.ORGNL_CASE_MNG_NO AS ORGNL_CASE_MNG_NO , T6.PVSN_RESRCE_NM , T6.RESRCE_NO , T4.BGNG_YMD , T4.END_YMD , T4.FNSH_YMD , ROWNUM AS SEQ FROM SEB100 T1 , SEA201 T2 , SCA100 X , SEB150 Y , SAA000 Z , SEB510 T5 , SDA100 T6 , AFA330 T4 WHERE 1=1 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO AND T2.MDFCN_DT = ( SELECT MAX(MDFCN_DT) FROM SEA201 WHERE TRPR_INFO_NO = T2.TRPR_INFO_NO AND NVL(TRMN_CASE_MNG_NO, '1') = CASE WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('04','08','10','11') THEN T1.CASE_MNG_NO ELSE '1' END AND NVL(TRMN_CASE_MNG_ODRNO, 1) = CASE WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('04','08','10','11') THEN T1.CASE_MNG_ODRNO ELSE 1 END ) AND Z.INST_NO = Y.PIC_INST_NO AND X.ENFSN_NO = Y.CASE_PIC_NO AND Y.PCHPRS_YN = 'Y' AND Y.CASE_MNG_NO = T1.CASE_MNG_NO AND Y.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND T5.CASE_MNG_NO = T1.CASE_MNG_NO AND T5.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND T5.RESRCE_NO = T6.RESRCE_NO AND T5.DEL_YN = 'N' AND T6.SRVC_RESRCE_LCLAS_SE_CD NOT IN ('01') AND T4.CASE_MNG_NO(+) = T5.CASE_MNG_NO AND T4.CASE_MNG_ODRNO(+) = T5.CASE_MNG_ODRNO
) T1 WHERE 1 = 1
AND T1.SEQ >= #{START_IDX} AND T1.SEQ <= #{LAST_IDX}

mapper.sql:



          /* 진행일자 조회 */
          AND T1.CASE_BGNG_YMD <= #{END_DATE} AND NVL(T1.CASE_TRMN_YMD, T1.CASE_BGNG_YMD) >= #{START_DATE}




          /* 등록일자 조회 */
          AND T1.FRST_REG_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
          AND T1.FRST_REG_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')





   AND T1.CASE_PRGRS_STTS_SE_CD IN (SELECT CMMNS_CD_VALUE FROM SAC100
                                     WHERE CMMNS_CD_ID       = 'CASE_PRGRS_STTS_SE_CD'
                                       AND UP_CMMNS_CD_VALUE = #{CASE_PRGRS_STTS_SE_CD})




   AND T1.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}


/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/

/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/


  AND T1.YNGBGS_SE_NO LIKE '%' || #{YNGBGS_STTS_LCLAS_SE_CD} || '%'




  AND T1.YNGBGS_STTS_SCLAS_SE_CD = #{YNGBGS_STTS_SCLAS_SE_CD}




  AND T2.CASE_TRPR_TYPE_SE_CD  = #{CASE_TRPR_TYPE_SE_CD}





  AND T2.RCPT_PIC_NO = #{USER_ID}





  AND #{SRVC_EXCN_BIZ_NO} IN (SELECT SRVC_EXCN_BIZ_NO
                                FROM SEB120
                               WHERE CASE_MNG_NO     = T1.CASE_MNG_NO
                                 AND CASE_MNG_ODRNO  = T1.CASE_MNG_ODRNO
                                 AND DEL_YN         != 'Y')




  AND #{APRV_YN}  = NVL(( SELECT APRV_YN
                            FROM AFA410
                           WHERE CASE_MNG_NO    = T1.CASE_MNG_NO
                             AND CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO
                        ),'N')




    AND X.FLNM_ENCPT = ENC_B64(#{PIC_NM_ENCPT})




    AND T2.TRPR_NM_ENCPT = ENC_B64(#{TRPR_NM_ENCPT})




    AND(Y.PIC_INST_NO       = #{INST_NO}
     OR Z.INST_NM           = #{INST_NM})



    AND X.JBPS_SE_CD = #{JBPS_SE_CD}


    AND T1.ORGNL_CASE_MNG_NO IS NOT NULL


    AND T6.RESRCE_NO = #{RESRCE_NO}

mapper.update:
    MERGE INTO AFA330 A
	USING DUAL
	    ON
	    (
	        A.CASE_MNG_NO = #{CASE_MNG_NO}
	        AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
	    )
	WHEN MATCHED THEN
	    UPDATE SET
	          A.BGNG_YMD = #{BGNG_YMD}
	        , A.END_YMD = #{END_YMD}
	        , A.FNSH_YMD = #{FNSH_YMD}
	        , LAST_MDFR_ID = #{USER_ID}
	        , LAST_MDFCN_DT = SYSDATE
	    WHERE A.CASE_MNG_NO = #{CASE_MNG_NO}
	        AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
	WHEN NOT MATCHED THEN
	    INSERT (
	          CASE_MNG_NO
	        , CASE_MNG_ODRNO
	        , BGNG_YMD
	        , END_YMD
	        , FNSH_YMD
	        , FRST_RGTR_ID
	        , FRST_REG_DT
	        , LAST_MDFR_ID
	        , LAST_MDFCN_DT
	    ) VALUES (
	          #{CASE_MNG_NO}
	        , #{CASE_MNG_ODRNO}
	        , #{BGNG_YMD}
	        , #{END_YMD}
	        , #{FNSH_YMD}
	        , #{USER_ID}
	        , SYSDATE
	        , #{USER_ID}
	        , SYSDATE
	    )

mapper.select:
SELECT
/* isry.aimns.casemng.mapper.AimnsCaseMngMapper.selectCaseinqList */ TT.* , A.UP_CMMNS_CD_VALUE AS CASE_PRGRS_STTS_TYPE_SE_CD /* 사례진행상태유형구분코드 */ , TO_CHAR(TT.FRST_REG_DT2, 'YYYY-MM-DD') AS FRST_REG_DT /* 등록일자 */ FROM ( SELECT T99.* FROM ( SELECT /*+ INDEX_DESC(T1 SEB100_PK)*/ T1.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , T1.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , T1.FRST_REG_DT AS FRST_REG_DT2 /* 등록일자 */ , T2.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , C##RG.DEC_B64(T2.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /* 대상자명 */ , TO_CHAR(TO_DATE(REPLACE(T2.TRPR_BRTH_YMD, '-', '')), 'YYYY-MM-DD') AS TRPR_BRTH_YMD /* 대상자출생일자 */ , T2.SXDC_SE_CD AS SXDC_SE_CD /* 대상자성별구분코드 */ , T1.YNGBGS_STTS_LCLAS_SE_CD AS YNGBGS_STTS_LCLAS_SE_CD /* 청소년상태대분류구분코드 */ , T1.YNGBGS_STTS_SCLAS_SE_CD AS YNGBGS_STTS_SCLAS_SE_CD /* 청소년상태소분류구분코드 */ , T1.YNGBGS_SE_NO AS YNGBGS_SE_NO /* 청소년구분번호 */ , C##RG.DEC_B64(X.FLNM_ENCPT) AS PIC_NM_ENCPT /* 담당자명(주담당자기준) */ , Y.PIC_INST_NO AS PIC_INST_NO /* 담당기관(주담당자기준) */ , CASE WHEN X.JBPS_NM IS NOT NULL THEN X.JBPS_NM ELSE (SELECT TT1.CMMNS_CD_VALUE_NM FROM SAC100 TT1 WHERE TT1.CMMNS_CD_ID = 'JBPS_SE_CD' AND TT1.CMMNS_CD_VALUE = X.JBPS_SE_CD) END AS JBPS_NM /* 담당자직위명(주담당자기준) */ , X.JBPS_SE_CD AS JBPS_SE_CD /* 담당자직위구분코드(주담당자기준) */ , Z.INST_NM AS INST_NM /* 담당기관명(주담당자기준) */ , T2.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , T1.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , T1.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , T2.TRMN_CASE_MNG_NO AS TRMN_CASE_MNG_NO /* 종결사례관리번호 */ , T2.TRMN_CASE_MNG_ODRNO AS TRMN_CASE_MNG_ODRNO /* 종결사례관리차수 */ , T1.CASE_BGNG_YMD AS CASE_BGNG_YMD , T1.CASE_TRMN_YMD AS CASE_TRMN_YMD , CASE WHEN T1.CASE_PRGRS_STTS_SE_CD = '01' THEN 'REG' /* 등록 */ WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('02','03','06','12') THEN 'PRGRS' /* 진행 */ WHEN T1.CASE_PRGRS_STTS_SE_CD IN ('04','08','10') THEN 'TRMN' /* 종결 */ ELSE '' END AS STEP_SE , T2.RCPT_PIC_NO AS RCPT_PIC_NO , Z.CTPV_CD AS CTPV_CD , T1.ORGNL_CASE_MNG_NO AS ORGNL_CASE_MNG_NO , ROWNUM AS SEQ , (SELECT b.PVSN_RESRCE_NM FROM SEB510 a, SDA100 b WHERE ROWNUM = 1 AND a.RESRCE_NO = b.RESRCE_NO AND a.CASE_MNG_NO = T1.CASE_MNG_NO AND a.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND b.SRVC_TYPE_SE_CD = '04' AND b.SRVC_RESRCE_LCLAS_SE_CD = '08' AND a.DEL_YN = 'N' ) AS PVSN_RESRCE_NM , T3.BGNG_YMD AS COMPL_BGNG_YMD , T3.END_YMD AS COMPL_END_YMD FROM SEB100 T1 , SEA200 T2 , SCA100 X , SEB150 Y , SAA000 Z , AFA330 T3 WHERE 1=1 AND T1.TRPR_INFO_NO = T2.TRPR_INFO_NO AND Z.INST_NO = Y.PIC_INST_NO AND X.ENFSN_NO = Y.CASE_PIC_NO AND Y.PCHPRS_YN = 'Y' AND Y.CASE_MNG_NO = T1.CASE_MNG_NO AND Y.CASE_MNG_ODRNO = T1.CASE_MNG_ODRNO AND T1.CASE_MNG_NO = T3.CASE_MNG_NO(+) AND T1.CASE_MNG_ODRNO = T3.CASE_MNG_ODRNO(+)
) T99 WHERE 1 = 1
AND T99.SEQ >= #{START_IDX} AND T99.SEQ <= #{LAST_IDX}
) TT, SAC100 A WHERE TT.CASE_PRGRS_STTS_SE_CD = A.CMMNS_CD_VALUE(+) AND 'CASE_PRGRS_STTS_SE_CD' = A.CMMNS_CD_ID(+)

choose.otherwise:

/* 등록일자 조회 */
AND T1.FRST_REG_DT >= TO_DATE(#{START_DATE} || '000000', 'YYYYMMDDHH24MISS')
AND T1.FRST_REG_DT <= TO_DATE(#{END_DATE} || '235959', 'YYYYMMDDHH24MISS')

choose.when:

AND (T1.CASE_MNG_NO, T1.CASE_MNG_ODRNO)
    IN (SELECT YY.CASE_MNG_NO,YY.CASE_MNG_ODRNO
        FROM SEB150 YY
        WHERE 1=1
        AND YY.PIC_INST_NO = #{INST_NOS[0]}

   )

choose.otherwise:

	                AND EXISTS (SELECT 1 FROM SEB150 YY
	                WHERE T1.CASE_MNG_NO = YY.CASE_MNG_NO
	                AND T1.CASE_MNG_ODRNO = YY.CASE_MNG_ODRNO
	                AND YY.PIC_INST_NO IN


                            #{item}

	                )

sql.if:

AND EXISTS (SELECT 1 FROM SEB120 B
WHERE B.CASE_MNG_NO     = T1.CASE_MNG_NO
  AND B.CASE_MNG_ODRNO  = T1.CASE_MNG_ODRNO
  AND B.DEL_YN         = 'N'
  AND B.SRVC_EXCN_BIZ_NO = #{SRVC_EXCN_BIZ_NO}
)


AND EXISTS (SELECT 1 FROM AFA410 B
WHERE B.CASE_MNG_NO     = T1.CASE_MNG_NO
 AND B.CASE_MNG_ODRNO   = T1.CASE_MNG_ODRNO
 AND B.APRV_YN          = #{APRV_YN}
)


AND EXISTS (SELECT 1 FROM SEB510 B
WHERE B.CASE_MNG_NO     = T1.CASE_MNG_NO
  AND B.CASE_MNG_ODRNO  = T1.CASE_MNG_ODRNO
  AND B.DEL_YN         = 'N'
  AND B.RESRCE_NO = #{RESRCE_NO}
)
